// Read genuine pre-assessment objects through the current worker and Panel.
// Use a dedicated synthetic workspace generated by the frozen old provider.
// Never relocate its bound paths or synthesize legacy by editing a new object.
// CLI: repo python legacy-workspace fresh-output-directory.
import assert from 'node:assert/strict';
import {mkdirSync, readFileSync, readdirSync, writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import path from 'node:path';
import {pathToFileURL} from 'node:url';

const [repo, python, original, output] = process.argv.slice(2);
for (const p of [repo, python, original, output]) assert.ok(path.isAbsolute(p));
mkdirSync(output, {recursive: false});
const hashes = root => {
  const result = {};
  const visit = dir => {for (const e of readdirSync(dir, {withFileTypes: true})) {
    assert.ok(!e.isSymbolicLink()); const file = path.join(dir, e.name);
    if (e.isDirectory()) visit(file);
    else result[path.relative(root, file)] = createHash('sha256').update(readFileSync(file)).digest('hex');
  }};
  visit(root); return result;
};
const before = hashes(original), workspace = original;
assert.equal(path.basename(workspace), 'images');
const config = path.join(output, 'config.json');
writeFileSync(config, JSON.stringify({schema_version: 1, python, workspace_root: path.dirname(workspace), structures: false}));
process.env.MICROSCOPY_PLUGIN_CONFIG = config;
const {StdioImageClient, createImagePanel} = await import(pathToFileURL(path.join(repo, 'dist/tools/image_panel.mjs')));
const {prepareOwnedPanelRegistration} = await import(pathToFileURL(path.join(repo, 'dist/lib/panel_ownership.mjs')));
const {gpaEvidenceModel} = await import(pathToFileURL(path.join(repo, 'dist/ui/image-panel/gpa-evidence.mjs')));
const client = new StdioImageClient({workspace, python, serverPath: path.join(repo, 'dist/tools/plugin_server.mjs')});
const report = {scope: 'Genuine old objects; current Python + formal stdio MCP + owned HTTP Panel, synthetic sources only',
  original_workspace: original, original_file_hashes: before, reads: [], panels: [], new_views: []};
try {
  await client.rpc('initialize');
  const saved = readdirSync(path.join(workspace, 'requests')).map(name => JSON.parse(readFileSync(path.join(workspace, 'requests', name), 'utf8')))
    .filter(r => ['gpa', 'gpa_read', 'gpa_view'].includes(r.response?.kind));
  assert.ok(saved.length > 0);
  for (const record of saved) {
    assert.equal(Object.hasOwn(record.response, 'evidence_assessment'), false);
    const recovered = (await client.tool('image_result', {request_id: record.request_id})).data;
    const {ok, ...expected} = record.response;
    assert.deepEqual(recovered, expected);
    const info = (await client.tool('image_info', {object_id: record.response.object_id})).data;
    assert.equal(Object.hasOwn(info, 'evidence_assessment'), false);
    report.reads.push({object_id: info.object_id, kind: info.kind, request_id: record.request_id, exact_recovery: true, assessment_absent: true});
  }
  const parent = saved.find(r => r.response.kind === 'gpa').response;
  const view = (await client.tool('image_gpa_view', {object_id: parent.object_id, component: 'exx',
    request_id: 'boundary-history-view', max_size: 512})).data;
  assert.equal(Object.hasOwn(view, 'evidence_assessment'), false);
  report.new_views.push({object_id: view.object_id, parent_object_id: parent.object_id, assessment_absent: true});
  for (const object of [parent, view]) {
    const panelId = createHash('sha256').update(output + object.object_id).digest('hex').slice(0, 32);
    const owned = prepareOwnedPanelRegistration({workspace, panel_id: panelId});
    let panel;
    try {
      panel = await createImagePanel({workspace, python, object_id: object.object_id, panel_id: panelId,
        helper_session_id: owned.helper_session_id, panel_generation: owned.generation, journalDirectory: owned.journalDirectory});
      owned.publish(panel);
      const response = await fetch(panel.url.split('/#')[0] + '/api/state', {headers: {'X-Panel-Token': panel.token}});
      assert.equal(response.status, 200); const http = await response.json();
      const mcp = (await client.tool('image_panel_current', {panel_id: panelId})).data;
      for (const projection of [http.object, mcp.view.object]) {
        assert.equal(Object.hasOwn(projection, 'evidence_assessment'), false);
        assert.equal(Object.hasOwn(projection, 'evidence_assessment_projection'), false);
        assert.equal(gpaEvidenceModel(projection).status, 'not_recorded');
      }
      report.panels.push({object_id: object.object_id, kind: object.kind, http_object: http.object,
        mcp_object: mcp.view.object, renderer_status: 'not_recorded'});
    } finally {if (panel) await owned.close(panel);}
  }
  const after = hashes(workspace);
  for (const [file, sha] of Object.entries(before)) assert.equal(after[file], sha, file);
  report.original_files_unchanged = Object.keys(before).length;
  report.result = 'PASS';
} catch (error) {report.result = 'FAIL'; report.error = error.stack; throw error;}
finally {
  await client.close(); writeFileSync(path.join(output, 'report.json'), JSON.stringify(report, null, 2) + '\n');
}
console.log(JSON.stringify({result: report.result, reads: report.reads.length, panels: report.panels.length,
  original_files_unchanged: report.original_files_unchanged}));
